import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from './lib/args.mjs';
import { loadContext } from './lib/config.mjs';
import { fetchSitemap } from './lib/sitemap.mjs';
import { get, pool, norm, concurrencyFor } from './lib/http.mjs';
import { printResult, toMarkdown } from './lib/report.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ORDER = ['a11y', 'redirects', 'links', 'floor', 'doorway', 'linktopics', 'wikidata', 'crawl', 'canonicals'];
const FILES = { crawl: 'crawl', canonicals: 'canonicals', redirects: 'redirects', links: 'internal-links', a11y: 'a11y-tree', linktopics: 'link-topics', doorway: 'doorway-ratio', floor: 'granularity-floor', wikidata: 'wikidata' };

export async function loadChecks() {
  const out = {};
  for (const id of ORDER) out[id] = (await import(`./checks/${FILES[id]}.mjs`)).default;
  return out;
}

export async function run(argv) {
  const args = parseArgs(argv, { booleans: ['json', 'static', 'live', 'strict', 'fix', 'update', 'report-only', 'es', 'help', 'quiet'] });
  if (args.help) { console.log(fs.readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').filter(l => l.startsWith('//')).map(l => l.slice(3)).join('\n')); return 0; }
  const ctx = await loadContext(args);
  ctx.concurrency = concurrencyFor(ctx.base || 'http://localhost', args.concurrency);
  ctx.timeoutMs = Number(args.timeout) || 20000;
  const checks = await loadChecks();
  const wanted = args._.filter(a => !['static', 'live', 'all'].includes(a));
  const ids = wanted.length ? wanted : ORDER;
  for (const id of ids) if (!checks[id]) { console.error(`unknown check "${id}" — one of ${ORDER.join(' ')}`); return 2; }
  const runStatic = !args.live && !args._.includes('live');
  const runLive = Boolean(ctx.base) && !args.static && !args._.includes('static');
  if (!runStatic && !runLive) { console.error('nothing to run: --live needs --base'); return 2; }

  const log = args.json || args.quiet ? () => {} : (...a) => console.log(...a);
  log(`site-health · ${ctx.client.name} (${ctx.client.slug}) · ${ctx.framework} · repo ${ctx.repo}${ctx.base ? ` · base ${ctx.base}` : ''}`);

  if (runLive) {
    ctx.sitemap = await fetchSitemap(ctx.base, { sitemap: args.sitemap });
    ctx.pages = new Map();
    const t0 = Date.now();
    await pool(ctx.sitemap.paths, ctx.concurrency, async (p) => {
      const res = await get(ctx.base + p, { timeoutMs: ctx.timeoutMs });
      ctx.pages.set(norm(p), { path: p, status: res.status, location: res.location, html: res.text, error: res.error });
    });
    const ok = [...ctx.pages.values()].filter(p => p.status === 200).length;
    log(`fetched ${ctx.pages.size} sitemap pages (${ok} × 200) in ${((Date.now() - t0) / 1000).toFixed(1)}s at concurrency ${ctx.concurrency}${ctx.sitemap.children.length ? ` · sitemap index with ${ctx.sitemap.children.length} children` : ''}`);
  }

  const results = [];
  for (const id of ids) {
    const chk = checks[id];
    const modes = chk.modes.filter(m => (m === 'static' && runStatic) || (m === 'live' && runLive));
    for (const mode of modes) {
      let r;
      try { r = await chk.run(ctx, mode); }
      catch (e) { r = { id, title: chk.title, pass: false, gating: true, skipped: false, summary: [`crashed: ${e.stack || e.message}`], findings: [], stats: {} }; }
      r.mode = mode;
      if (chk.modes.length > 1 && modes.length > 1) r.title = `${chk.title} (${mode === 'live' ? 'rendered' : 'source'})`;
      results.push(r);
      if (!args.json) printResult(r);
    }
  }
  const pass = results.every(r => r.skipped || r.pass || !r.gating);
  const report = { generatedAt: new Date().toISOString(), client: { slug: ctx.client.slug, name: ctx.client.name }, repo: ctx.repo, base: ctx.base, framework: ctx.framework, pass, checks: results };
  if (args.json) console.log(JSON.stringify(report, null, 2));
  if (args.out) { fs.mkdirSync(path.dirname(path.resolve(args.out)), { recursive: true }); fs.writeFileSync(args.out, JSON.stringify(report, null, 2)); }
  if (args.md) fs.appendFileSync(args.md, toMarkdown(report));
  const failed = results.filter(r => !r.skipped && !r.pass && r.gating).map(r => r.id);
  if (!args.json) console.log(`\n${pass ? 'OK' : 'FAIL'} — ${results.length} check run(s)${failed.length ? `, failing: ${failed.join(', ')}` : ''}${args['report-only'] && !pass ? ' (report-only: exit 0)' : ''}`);
  return pass || args['report-only'] ? 0 : 1;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  // exitCode, not exit(): a large --json report piped to another process is
  // truncated at 64 KB if the process exits before stdout drains.
  run(process.argv.slice(2)).then(code => { process.exitCode = code; }, e => { console.error(e.stack || e.message); process.exitCode = 2; });
}
